Description: Create Appointment
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "title": "Patient Id"
        },
        "doctor_id": {
          "type": "integer",
          "title": "Doctor Id"
        },
        "scheduled_at": {
          "type": "string",
          "title": "Scheduled At"
        },
        "duration_minutes": {
          "type": "integer",
          "title": "Duration Minutes",
