          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Reason"
        },
        "recurrence_rule": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Recurrence Rule"
        }
      },
      "required": [
        "patient_id",
        "doctor_id",
        "scheduled_at"
      ]
    }
